    font-size: 0.7rem;
    font-weight: 700;
    width: 16px;
    height: 16px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* Hero */
.hero {
    padding: 8rem 0;
    background: linear-gradient(45deg, #0a0a0a 0%, #151515 100%);
    position: relative;
}

.hero-container {
    display: grid;
    grid-template-columns: 1.2fr 1fr;
    gap: 4rem;
    align-items: center;
}

.hero-content h1 {
    font-size: clamp(3rem, 8vw, 5rem);
    line-height: 1.1;
    margin-bottom: 2rem;
    font-weight: 700;
}

.hero-content p {
    font-size: 1.25rem;
    color: var(--text-muted);
    margin-bottom: 3rem;
    max-width: 500px;
}

.hero-cta {
    display: flex;
    gap: 1.5rem;
}

.hero-image {
    aspect-ratio: 4/5;
    background-color: var(--surface-color);
    border: 1px solid var(--border-color);
    position: relative;
}

.hero-image::after {
    content: "";
    position: absolute;
    top: 20px;
    right: -20px;
    bottom: -20px;
    left: 20px;
    border: 1px solid var(--border-color);
    z-index: -1;
}

/* Sections */
section {
    padding: 6rem 0;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: 3rem;
}

h2 {
    font-size: 2.5rem;
    letter-spacing: -0.5px;
}

/* Deal Cards */
.deal-grid, .product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 2rem;
}

.deal-card, .product-card {
    background-color: var(--surface-color);
    border: 1px solid var(--border-color);
    transition: var(--transition);
    position: relative;
}

.deal-card:hover, .product-card:hover {
    border-color: var(--accent-color);
    transform: translateY(-5px);
}

.card-image {
    aspect-ratio: 1;
    background-color: #111;
    overflow: hidden;
}

.card-body {
    padding: 1.5rem;
}

.card-body h3 {
    font-size: 1.25rem;
    margin-bottom: 0.5rem;
}

.price {
    font-size: 1.1rem;
    margin-bottom: 1.5rem;
}

.price .current {
    font-weight: 700;
}

.price .old {
    text-decoration: line-through;
    color: var(--text-muted);
    font-size: 0.9rem;
    margin-left: 0.5rem;
}

.deal-badge {
    position: absolute;
    top: 1rem;
    left: 1rem;
    background-color: var(--accent-color);
    color: var(--bg-color);
    padding: 0.25rem 0.75rem;
    font-size: 0.75rem;
    font-weight: 700;
    z-index: 10;
}

/* Timer */
.timer {
    font-family: monospace;
    font-size: 1.25rem;
    background-color: var(--surface-color);
    padding: 0.5rem 1rem;
    border: 1px solid var(--border-color);
}

/* Editorial */
.editorial {
    background-color: var(--surface-color);
    padding: 0;
}

.editorial-container {
    display: grid;
    grid-template-columns: 1fr 1fr;
}

.editorial-image {
    height: 600px;
    background-color: #000;
}

.editorial-content {
    padding: 6rem;
    display: flex;
    flex-direction: column;
    justify-content: center;
}

.editorial-content .label {
    text-transform: uppercase;
    letter-spacing: 2px;
    color: var(--text-muted);
    font-size: 0.8rem;
    margin-bottom: 1rem;
}

.editorial-content h2 {
    margin-bottom: 1.5rem;
}

.editorial-content p {
    color: var(--text-muted);
    font-size: 1.1rem;
    margin-bottom: 2rem;
}

.read-more {
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1px;
    border-bottom: 1px solid var(--accent-color);
    align-self: flex-start;
}

/* Footer */
.site-footer {
    background-color: #000;
    padding: 6rem 0 2rem;
    border-top: 1px solid var(--border-color);
}

.footer-grid {
    display: grid;
    grid-template-columns: 2fr 2fr 1.5fr;
    gap: 4rem;
    margin-bottom: 4rem;
}

.footer-brand .logo {
    margin-bottom: 1.5rem;
}

.footer-nav {
    display: grid;
    grid-template-columns: 1fr 1fr;
}

.footer-col h4 {
    margin-bottom: 1.5rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-size: 0.9rem;
}

.footer-col ul li {
    margin-bottom: 0.75rem;
}

.footer-col a {
    color: var(--text-muted);
    font-size: 0.9rem;
}

.footer-col a:hover {
    color: var(--accent-color);
}

.footer-newsletter h4 {
    margin-bottom: 1rem;
}

.footer-newsletter p {
    color: var(--text-muted);
    font-size: 0.9rem;
    margin-bottom: 1.5rem;
}

.newsletter-form .form-group {
    display: flex;
    gap: 0;
}

.newsletter-form input {
    background-color: var(--surface-color);
    border: 1px solid var(--border-color);
    color: var(--text-color);
    padding: 0.75rem;
    flex-grow: 1;
    font-family: inherit;
}

.newsletter-form input:focus {
    outline: none;
    border-color: var(--accent-color);
}

.footer-bottom {
    padding-top: 2rem;
    border-top: 1px solid var(--border-color);
    color: var(--text-muted);
    font-size: 0.8rem;
    text-align: center;
}

/* Responsive */
@media (max-width: 992px) {
    .hero-container {
        grid-template-columns: 1fr;
        text-align: center;
    }
    .hero-content {
        order: 2;
    }
    .hero-image {
        order: 1;
        max-width: 400px;
        margin: 0 auto;
    }
    .hero-content p {
        margin-left: auto;
        margin-right: auto;
    }
    .hero-cta {
        justify-content: center;
    }
    .editorial-container {
        grid-template-columns: 1fr;
    }
    .editorial-image {
        height: 300px;
    }
    .editorial-content {
        padding: 4rem 2rem;
    }
    .footer-grid {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 768px) {
    .main-nav {
        display: none; /* In a real app, I'd add a hamburger menu */
    }
    .section-header {
        flex-direction: column;
        align-items: flex-start;
        gap: 1rem;
    }
}
