+document.addEventListener('DOMContentLoaded', () => {
+    // 1. Countdown Timer for Deals
+    const countdownElement = document.getElementById('countdown');
+    
+    // Set target date (24 hours from now for demonstration)
+    const targetDate = new Date();
+    targetDate.setHours(targetDate.getHours() + 24);
+
+    function updateTimer() {
+        const now = new Date().getTime();
+        const distance = targetDate - now;
+
+        if (distance < 0) {
+            countdownElement.textContent = "00:00:00";
+            return;
+        }
+
+        const hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
+        const minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
+        const seconds = Math.floor((distance % (1000 * 60)) / 1000);
+
+        const hDisplay = hours < 10 ? '0' + hours : hours;
+        const mDisplay = minutes < 10 ? '0' + minutes : minutes;
+        const sDisplay = seconds < 10 ? '0' + seconds : seconds;
+
+        countdownElement.textContent = `${hDisplay}:${mDisplay}:${sDisplay}`;
+    }
+
+    setInterval(updateTimer, 1000);
+    updateTimer();
+
+    // 2. Add to Cart Simulation
+    const cartCountElement = document.querySelector('.cart-count');
+    const cartBtn = document.querySelector('.cart-btn');
+    const addToCartButtons = document.querySelectorAll('.add-to-cart');
+    let cartCount = 0;
+
+    function updateCart(productName) {
+        cartCount++;
+        cartCountElement.textContent = cartCount;
+        cartBtn.setAttribute('aria-label', `View shopping cart, ${cartCount} items`);
+        
+        // Simple visual feedback
+        const notification = document.createElement('div');
+        notification.className = 'cart-notification';
+        notification.setAttribute('role', 'status');
+        notification.setAttribute('aria-live', 'polite');
+        notification.textContent = `Added ${productName} to cart`;
+        notification.style.cssText = `
+            position: fixed;
+            bottom: 20px;
+            right: 20px;
+            background: var(--accent-color);
+            color: var(--bg-color);
+            padding: 1rem;
+            font-weight: bold;
+            z-index: 1000;
+        `;
+        document.body.appendChild(notification);
+
+        setTimeout(() => {
+            notification.remove();
+        }, 3000);
+    }
+
+    addToCartButtons.forEach(button => {
+        button.addEventListener('click', () => {
+            const name = button.getAttribute('data-name');
+            updateCart(name);
+        });
+    });
+
+    // 3. Newsletter form submission
+    const newsletterForm = document.querySelector('.newsletter-form');
+    newsletterForm.addEventListener('submit', (e) => {
+        e.preventDefault();
+        const email = newsletterForm.querySelector('input').value;
+        alert(`Thank you for subscribing, ${email}!`);
+        newsletterForm.reset();
+    });
+
+    // 4. Smooth scrolling for anchor links
+    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
+        anchor.addEventListener('click', function (e) {
+            const targetId = this.getAttribute('href');
+            if (targetId === '#') return;
+            
+            e.preventDefault();
