    background: none;
}

img {
    max-width: 100%;
    display: block;
}

/* Accessibility */
.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
}

.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--accent-color);
    color: var(--bg-color);
    padding: 8px;
    z-index: 1000;
    transition: top 0.3s;
}

.skip-link:focus {
    top: 0;
}

:focus-visible {
    outline: 2px solid var(--accent-color);
    outline-offset: 4px;
}

/* Buttons */
.btn {
    display: inline-block;
    padding: 0.75rem 1.5rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1px;
    border-radius: 0;
    transition: var(--transition);
}

.btn-sm {
    padding: 0.5rem 1rem;
    font-size: 0.8rem;
}

.btn-primary {
    background-color: var(--accent-color);
    color: var(--bg-color);
}

.btn-primary:hover {
    background-color: var(--accent-hover);
}

.btn-secondary {
    background-color: transparent;
    color: var(--accent-color);
    border: 1px solid var(--accent-color);
}

.btn-secondary:hover {
    background-color: rgba(255, 255, 255, 0.1);
}

.btn-outline {
    border: 1px solid var(--border-color);
    color: var(--text-color);
}

.btn-outline:hover {
    border-color: var(--accent-color);
    background-color: var(--accent-color);
    color: var(--bg-color);
}

/* Header */
.site-header {
    background-color: rgba(10, 10, 10, 0.95);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--border-color);
    padding: 1.5rem 0;
    position: sticky;
    top: 0;
    z-index: 100;
}

.header-content {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    font-size: 1.5rem;
    font-weight: 800;
    letter-spacing: 4px;
}

.main-nav ul {
    display: flex;
    gap: 2rem;
}

.main-nav a {
    font-size: 0.9rem;
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: var(--text-muted);
}

.main-nav a:hover {
    color: var(--accent-color);
}

.header-actions {
    display: flex;
    gap: 1.5rem;
    align-items: center;
}

.cart-btn {
    position: relative;
    color: var(--text-color);
}

.cart-count {
    position: absolute;
    top: -8px;
    right: -8px;
    background-color: var(--accent-color);
    color: var(--bg-color);
    font-size: 0.7rem;
    font-weight: 700;
    width: 16px;
    height: 16px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* Hero */
.hero {
    padding: 8rem 0;
    background: linear-gradient(45deg, #0a0a0a 0%, #151515 100%);
    position: relative;
}

.hero-container {
    display: grid;
    grid-template-columns: 1.2fr 1fr;
    gap: 4rem;
    align-items: center;
}

.hero-content h1 {
    font-size: clamp(3rem, 8vw, 5rem);
    line-height: 1.1;
    margin-bottom: 2rem;
    font-weight: 700;
}

.hero-content p {
    font-size: 1.25rem;
    color: var(--text-muted);
    margin-bottom: 3rem;
    max-width: 500px;
}

.hero-cta {
    display: flex;
    gap: 1.5rem;
}

.hero-image {
    aspect-ratio: 4/5;
    background-color: var(--surface-color);
    border: 1px solid var(--border-color);
    position: relative;
}

.hero-image::after {
    content: "";
    position: absolute;
    top: 20px;
    right: -20px;
    bottom: -20px;
    left: 20px;
    border: 1px solid var(--border-color);
    z-index: -1;
}

/* Sections */
section {
    padding: 6rem 0;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: 3rem;
}

h2 {
    font-size: 2.5rem;
    letter-spacing: -0.5px;
}

/* Deal Cards */
.deal-grid, .product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 2rem;
}

.deal-card, .product-card {
    background-color: var(--surface-color);
    border: 1px solid var(--border-color);
    transition: var(--transition);
    position: relative;
}

.deal-card:hover, .product-card:hover {
    border-color: var(--accent-color);
    transform: translateY(-5px);
}

.card-image {
    aspect-ratio: 1;
    background-color: #111;
    overflow: hidden;
}

.card-body {
    padding: 1.5rem;
}

.card-body h3 {
    font-size: 1.25rem;
    margin-bottom: 0.5rem;
}

.price {
    font-size: 1.1rem;
    margin-bottom: 1.5rem;
}

.price .current {
    font-weight: 700;
}

.price .old {
    text-decoration: line-through;
    color: var(--text-muted);
    font-size: 0.9rem;
    margin-left: 0.5rem;
}

.deal-badge {
    position: absolute;
    top: 1rem;
    left: 1rem;
    background-color: var(--accent-color);
    color: var(--bg-color);
    padding: 0.25rem 0.75rem;
    font-size: 0.75rem;
    font-weight: 700;
    z-index: 10;
}

/* Timer */
.timer {
    font-family: monospace;
    font-size: 1.25rem;
    background-color: var(--surface-color);
    padding: 0.5rem 1rem;
    border: 1px solid var(--border-color);
}

/* Editorial */
.editorial {
    background-color: var(--surface-color);
    padding: 0;
}

.editorial-container {
    display: grid;
    grid-template-columns: 1fr 1fr;
}

.editorial-image {
    height: 600px;
    background-color: #000;
}

.editorial-content {
    padding: 6rem;
    display: flex;
    flex-direction: column;
    justify-content: center;
}

.editorial-content .label {
    text-transform: uppercase;
    letter-spacing: 2px;
    color: var(--text-muted);
    font-size: 0.8rem;
    margin-bottom: 1rem;
}

.editorial-content h2 {
    margin-bottom: 1.5rem;
}

.editorial-content p {
    color: var(--text-muted);
    font-size: 1.1rem;
    margin-bottom: 2rem;
}

.read-more {
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1px;
    border-bottom: 1px solid var(--accent-color);
    align-self: flex-start;
}

/* Footer */
.site-footer {
    background-color: #000;
    padding: 6rem 0 2rem;
    border-top: 1px solid var(--border-color);
}

.footer-grid {
    display: grid;
    grid-template-columns: 2fr 2fr 1.5fr;
    gap: 4rem;
    margin-bottom: 4rem;
}

.footer-brand .logo {
    margin-bottom: 1.5rem;
}

.footer-nav {
    display: grid;
    grid-template-columns: 1fr 1fr;
}

.footer-col h4 {
    margin-bottom: 1.5rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-size: 0.9rem;
}

.footer-col ul li {
    margin-bottom: 0.75rem;
}

.footer-col a {
    color: var(--text-muted);
    font-size: 0.9rem;
}

.footer-col a:hover {
    color: var(--accent-color);
}

.footer-newsletter h4 {
    margin-bottom: 1rem;
}

.footer-newsletter p {
    color: var(--text-muted);
    font-size: 0.9rem;
    margin-bottom: 1.5rem;
}

.newsletter-form .form-group {
    display: flex;
    gap: 0;
}

.newsletter-form input {
    background-color: var(--surface-color);
    border: 1px solid var(--border-color);
    color: var(--text-color);
    padding: 0.75rem;
    flex-grow: 1;
    font-family: inherit;
}

.newsletter-form input:focus {
    outline: none;
    border-color: var(--accent-color);
}

.footer-bottom {
    padding-top: 2rem;
    border-top: 1px solid var(--border-color);
    color: var(--text-muted);
    font-size: 0.8rem;
    text-align: center;
}

/* Animations */
@keyframes fadeIn {
    from { opacity: 0; transform: translateY(20px); }
    to { opacity: 1; transform: translateY(0); }
}

.hero-content, .deal-card, .product-card, .editorial-content {
    animation: fadeIn 0.8s ease-out forwards;
}

.deal-card:nth-child(2) { animation-delay: 0.2s; }
.product-card:nth-child(2) { animation-delay: 0.1s; }
.product-card:nth-child(3) { animation-delay: 0.2s; }
.product-card:nth-child(4) { animation-delay: 0.3s; }

/* Better visual placeholders */
.card-image, .hero-image, .editorial-image {
    background: linear-gradient(135deg, #1a1a1a 25%, #222 50%, #1a1a1a 75%);
    background-size: 200% 200%;
    animation: shimmer 5s infinite linear;
}

@keyframes shimmer {
    0% { background-position: -200% 0; }
    100% { background-position: 200% 0; }
}

@media (prefers-reduced-motion: reduce) {
    *, ::before, ::after {
        animation-delay: -1ms !important;
        animation-duration: 1ms !important;
        animation-iteration-count: 1 !important;
        background-attachment: initial !important;
        scroll-behavior: auto !important;
        transition-duration: 0s !important;
        transition-delay: 0s !important;
    }
}

@media (max-width: 992px) {
    .hero-container {
        grid-template-columns: 1fr;
        text-align: center;
    }
    .hero-content {
        order: 2;
    }
    .hero-image {
        order: 1;
        max-width: 400px;
        margin: 0 auto;
    }
    .hero-content p {
        margin-left: auto;
        margin-right: auto;
    }
    .hero-cta {
        justify-content: center;
    }
    .editorial-container {
        grid-template-columns: 1fr;
    }
    .editorial-image {
        height: 300px;
    }
    .editorial-content {
        padding: 4rem 2rem;
    }
    .footer-grid {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 768px) {
    .main-nav {
        display: none; /* In a real app, I'd add a hamburger menu */
    }
    .section-header {
        flex-direction: column;
        align-items: flex-start;
        gap: 1rem;
    }
}
