    margin-bottom: 1.5rem;
}

.price .current {
    font-weight: 700;
}

.price .old {
    text-decoration: line-through;
    color: var(--text-muted);
    font-size: 0.9rem;
    margin-left: 0.5rem;
}

.deal-badge {
    position: absolute;
    top: 1rem;
    left: 1rem;
    background-color: var(--accent-color);
    color: var(--bg-color);
    padding: 0.25rem 0.75rem;
    font-size: 0.75rem;
    font-weight: 700;
    z-index: 10;
}

/* Timer */
.timer {
    font-family: monospace;
    font-size: 1.25rem;
    background-color: var(--surface-color);
    padding: 0.5rem 1rem;
    border: 1px solid var(--border-color);
}

/* Editorial */
.editorial {
    background-color: var(--surface-color);
    padding: 0;
}

.editorial-container {
    display: grid;
    grid-template-columns: 1fr 1fr;
}

.editorial-image {
    height: 600px;
    background-color: #000;
}

.editorial-content {
    padding: 6rem;
    display: flex;
    flex-direction: column;
    justify-content: center;
}

.editorial-content .label {
    text-transform: uppercase;
    letter-spacing: 2px;
    color: var(--text-muted);
    font-size: 0.8rem;
    margin-bottom: 1rem;
}

.editorial-content h2 {
    margin-bottom: 1.5rem;
}

.editorial-content p {
    color: var(--text-muted);
    font-size: 1.1rem;
    margin-bottom: 2rem;
}

.read-more {
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1px;
    border-bottom: 1px solid var(--accent-color);
    align-self: flex-start;
}

/* Footer */
.site-footer {
    background-color: #000;
    padding: 6rem 0 2rem;
    border-top: 1px solid var(--border-color);
}

.footer-grid {
    display: grid;
    grid-template-columns: 2fr 2fr 1.5fr;
    gap: 4rem;
    margin-bottom: 4rem;
}

.footer-brand .logo {
    margin-bottom: 1.5rem;
}

.footer-nav {
    display: grid;
    grid-template-columns: 1fr 1fr;
}

.footer-col h4 {
    margin-bottom: 1.5rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-size: 0.9rem;
}

.footer-col ul li {
    margin-bottom: 0.75rem;
}

.footer-col a {
    color: var(--text-muted);
    font-size: 0.9rem;
}

.footer-col a:hover {
    color: var(--accent-color);
}

.footer-newsletter h4 {
    margin-bottom: 1rem;
}

.footer-newsletter p {
    color: var(--text-muted);
    font-size: 0.9rem;
    margin-bottom: 1.5rem;
}

.newsletter-form .form-group {
    display: flex;
    gap: 0;
}

.newsletter-form input {
    background-color: var(--surface-color);
    border: 1px solid var(--border-color);
    color: var(--text-color);
    padding: 0.75rem;
    flex-grow: 1;
    font-family: inherit;
}

.newsletter-form input:focus {
    outline: none;
    border-color: var(--accent-color);
}

.footer-bottom {
    padding-top: 2rem;
    border-top: 1px solid var(--border-color);
    color: var(--text-muted);
    font-size: 0.8rem;
    text-align: center;
}

/* Animations */
@keyframes fadeIn {
    from { opacity: 0; transform: translateY(20px); }
    to { opacity: 1; transform: translateY(0); }
}

.hero-content, .deal-card, .product-card, .editorial-content {
    animation: fadeIn 0.8s ease-out forwards;
}

.deal-card:nth-child(2) { animation-delay: 0.2s; }
.product-card:nth-child(2) { animation-delay: 0.1s; }
.product-card:nth-child(3) { animation-delay: 0.2s; }
.product-card:nth-child(4) { animation-delay: 0.3s; }

/* Better visual placeholders */
.card-image, .hero-image, .editorial-image {
    background: linear-gradient(135deg, #1a1a1a 25%, #222 50%, #1a1a1a 75%);
    background-size: 200% 200%;
    animation: shimmer 5s infinite linear;
}

@keyframes shimmer {
    0% { background-position: -200% 0; }
    100% { background-position: 200% 0; }
}

@media (prefers-reduced-motion: reduce) {
    *, ::before, ::after {
        animation-delay: -1ms !important;
        animation-duration: 1ms !important;
        animation-iteration-count: 1 !important;
        background-attachment: initial !important;
        scroll-behavior: auto !important;
        transition-duration: 0s !important;
        transition-delay: 0s !important;
    }
}

@media (max-width: 992px) {
    .hero-container {
        grid-template-columns: 1fr;
        text-align: center;
    }
    .hero-content {
        order: 2;
    }
    .hero-image {
        order: 1;
        max-width: 400px;
        margin: 0 auto;
    }
    .hero-content p {
        margin-left: auto;
        margin-right: auto;
    }
    .hero-cta {
        justify-content: center;
    }
    .editorial-container {
        grid-template-columns: 1fr;
    }
    .editorial-image {
        height: 300px;
    }
    .editorial-content {
        padding: 4rem 2rem;
    }
    .footer-grid {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 768px) {
    .main-nav {
        display: none; /* In a real app, I'd add a hamburger menu */
    }
    .section-header {
        flex-direction: column;
        align-items: flex-start;
        gap: 1rem;
    }
}
